package com.bank.benchmark;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class Top3Demo {
    private static final Logger log = Logger.getLogger("Benchmark");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "IT", 1000000),
            new Employee("Priya", "Sales", 900000),
            new Employee("Amit", "Risk", 700000),
            new Employee("Neha", "Ops", 400000));
        BenchmarkService service = new BenchmarkService();

        log.info(() -> "Top 3 depts by avg salary: " + service.top3ByAvgSalary(staff));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final String department;
    private final double salary;
    Employee(String name, String department, double salary) {
        this.name = name; this.department = department; this.salary = salary;
    }
    String getDepartment() { return department; }
    double getSalaryAsDouble() { return salary; }
}

// ─── Would be in service/BenchmarkService.java ───
class BenchmarkService {
    List<String> top3ByAvgSalary(List<Employee> staff) {
        Map<String, Double> avgByDept = staff.stream()
            .collect(groupingBy(Employee::getDepartment,
                averagingDouble(Employee::getSalaryAsDouble)));     // avg per dept
        return avgByDept.entrySet().stream()
            .sorted(Map.Entry.<String, Double>comparingByValue(Comparator.reverseOrder())
                .thenComparing(Map.Entry.comparingByKey()))          // rank desc, tie by name
            .limit(3)                                                // top 3
            .map(Map.Entry::getKey)
            .toList();
    }
}
